import React, { useMemo, useState } from 'react';
import { Box } from '@mui/material';
import { IUserInfo } from '../../core/Interface/user.interface';
import { IDashboard } from '../../core/Interface/dashboard.interface';
import { useGetDashboardQuery, useGetUserQuery } from '../posApi';
import { Privileges } from '../../core/types/commonType';
import useUser from '../../core/hooks/useUser';
import AlertPopup2 from './../../components/ModelPopup/AlertPopup2';
import HeroBanner from './component/HeroBanner';
import StatCardsGrid from './component/StatCardsGrid';
import ChartPanels from './component/ChartPanels';
import TablePanels from './component/TablePanels';

const TopInfo = () => {
  const { data, isLoading } = useGetDashboardQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });
  const { userHasRight } = useUser();

  const homeTop = useMemo(() => data?.data as IDashboard, [data?.data]);

  const transformedData = homeTop?.categoryProductCount?.data.map((item) => [
    item.key,
    item.value,
  ]);

  const yAxisData = homeTop?.dailySalesDetails?.data.map((item) =>
    parseFloat(item.value.replace(/[^\d.]/g, ''))
  );
  const xAxisData = homeTop?.dailySalesDetails?.data.map((item) => item.key);

  const { data: companyData } = useGetUserQuery();

  const loyalityList = homeTop?.loyalityDetails?.data ?? [];

  const [isPopupOpen, setIsPopupOpen] = useState(false);
  const alertText = useMemo(
    () => (companyData?.data as IUserInfo)?.alertText || null,
    [companyData]
  );

  React.useEffect(() => {
    setIsPopupOpen(!!alertText);
  }, [alertText]);

  const topItems = useMemo(
    () => homeTop?.topCard?.items || [],
    [homeTop]
  );

  const maxTopValue = useMemo(() => {
    const nums = topItems.map((i) => {
      const v = typeof i.value === 'string'
        ? parseFloat(String(i.value).replace(/[^\d.]/g, ''))
        : Number(i.value);
      return isNaN(v) ? 0 : v;
    });
    return Math.max(...nums, 0);
  }, [topItems]);

  return (
    <Box
      data-testid="dashboard"
      sx={{
        minHeight: '100%',
        // px: { xs: 2, md: 3 },
        // py: { xs: 2, md: 2.5 },
        overflow: 'hidden',
        background: 'white',
      }}
    >
      {alertText && (
        <AlertPopup2
          alertText={alertText}
          handleCloseAlert={() => setIsPopupOpen(false)}
          open={isPopupOpen}
        />
      )}

      <Box sx={{ position: 'relative', zIndex: 1, maxWidth: '1920px', mx: 'auto' }}>
        <HeroBanner
          isLoading={isLoading}
          topItems={topItems}
        />

        {userHasRight(Privileges.DashboardTodaySaleZone) && (
          <StatCardsGrid
            isLoading={isLoading}
            maxTopValue={maxTopValue}
            topItems={topItems}
          />
        )}

        <ChartPanels
          categoryProductCount={homeTop?.categoryProductCount}
          dailySalesDetails={homeTop?.dailySalesDetails}
          isLoading={isLoading}
          showCategory={userHasRight(Privileges.DashboardCategoryZone)}
          showWeeklySale={userHasRight(Privileges.DashboardWeeklySaleZone)}
          transformedData={transformedData}
          xAxisData={xAxisData}
          yAxisData={yAxisData}
        />

        <TablePanels
          filteredLoyalityList={loyalityList}
          isLoading={isLoading}
          loyalityDetails={homeTop?.loyalityDetails}
          productStockAlertDetails={homeTop?.productStockAlertDetails}
          salesProductCategoryDetails={homeTop?.salesProductCategoryDetails}
          showLoyality={userHasRight(Privileges.DashboardLoyality)}
          showProductAlert={userHasRight(Privileges.DashboardProductAlert)}
          showTrendingProduct={
            userHasRight(Privileges.DashboardTrendingProduct)
          }
        />
      </Box>
    </Box>
  );
};

export default TopInfo;
