import { getMetricValueFormat } from '../../../core/utils';
import { Typography, Box, Card, CardContent, Grid } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { IItem } from '../../../core/Interface/dashboard.interface';
import { appColors } from '../../../theme/appColors';
import TopInfoSkeleton from '../TopInfoSkeleton';
import React from 'react';

const accentColors = [
  '#F97316',
  '#06B6D4',
  '#8B5CF6',
  '#22C55E',
  '#0EA5E9',
  '#EC4899',
  '#F59E0B',
  '#14B8A6',
];

interface StatCardsGridProps {
  isLoading: boolean;
  topItems: IItem[];
  maxTopValue: number;
}

// eslint-disable-next-line max-len
const StatCardsGrid = ({ isLoading, topItems, maxTopValue }: StatCardsGridProps) => (
  <Grid
    container
    mb={2.5}
    spacing={{ xs: 1, sm: 1.5 }}
  >
    {isLoading
      ? [...Array(10)].map((_, i) => (
          <Grid
            item
            key={i}
            lg={3}
            md={4}
            sm={6}
            xl={2}
            xs={6}
          >
            <TopInfoSkeleton />
          </Grid>
        ))
      : topItems.slice(4).map((item, index) => {
          const accentColor = accentColors[index % accentColors.length];
          const numericValue = typeof item.value === 'string'
            ? parseFloat(String(item.value).replace(/[^\d.]/g, ''))
            : Number(item.value);
          const hasValue = !isNaN(numericValue) && numericValue > 0;
          // true share of the highest-value card — no artificial floor
          const shareOfPeak =
            maxTopValue > 0 && hasValue
              ? Math.min((numericValue / maxTopValue) * 100, 100)
              : 0;

          return (
            <Grid
              item
              key={`${item.key}-${index}`}
              lg={3}
              md={4}
              sm={6}
              xl={2}
              xs={6}
            >
              <Card
                sx={{
                  position: 'relative',
                  overflow: 'hidden',
                  minHeight: { xs: 104, sm: 120 },
                  borderRadius: '4px',
                  border: `1px solid ${alpha(accentColor, 0.22)}`,
                  background: `linear-gradient(145deg, rgba(255,255,255,0.98) 0%, ${alpha(accentColor, 0.08)} 100%)`,
                }}
              >
                <CardContent
                  sx={{
                    p: { xs: 1.5, sm: 2 },
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 1,
                    height: '100%',
                    '&:last-child': { pb: { xs: 1.5, sm: 2 } },
                  }}
                >
                  <Typography
                    sx={{
                      fontSize: { xs: '0.65rem', sm: '0.72rem' },
                      textTransform: 'uppercase',
                      letterSpacing: { xs: '0.06em', sm: '0.12em' },
                      wordBreak: 'break-word',
                      color: alpha(appColors.blueGreyishLight[80], 0.55),
                    }}
                  >
                    {item.key}
                  </Typography>

                  <Typography
                    sx={{
                      fontSize: { xs: '1rem', md: '1.25rem' },
                      wordBreak: 'break-word',
                      fontWeight: 700,
                      lineHeight: 1,
                      color: '#142352',
                      letterSpacing: '-0.02em',
                    }}
                  >
                    {getMetricValueFormat(item.key, item.value)}
                  </Typography>

                  <Box sx={{ mt: 'auto' }}>
                    <Box
                      sx={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        mb: 0.9,
                      }}
                    >
                      <Typography
                        sx={{
                          fontSize: { xs: '0.68rem', sm: '0.75rem' },
                          color: alpha(appColors.blueGreyishLight[80], 0.58),
                        }}
                      >
                        Share of peak
                      </Typography>

                      <Typography
                        sx={{
                          fontSize: '0.78rem',
                          fontWeight: 700,
                          color: hasValue ? accentColor : alpha(appColors.blueGreyishLight[80], 0.4),
                        }}
                      >
                        {hasValue ? (shareOfPeak < 1 ? '<1%' : `${Math.round(shareOfPeak)}%`) : '—'}
                      </Typography>
                    </Box>

                    <Box
                      sx={{
                        height: 6,
                        borderRadius: 999,
                        backgroundColor: alpha(accentColor, 0.14),
                        overflow: 'hidden',
                      }}
                    >
                      <Box
                        sx={{
                          width: `${shareOfPeak}%`,
                          height: '100%',
                          borderRadius: 999,
                          background: hasValue
                            ? `linear-gradient(90deg, ${accentColor} 0%, ${alpha(accentColor, 0.55)} 100%)`
                            : 'transparent',
                          transition: 'width 0.4s ease',
                        }}
                      />
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
  </Grid>
);

export default StatCardsGrid;
