import { getMetricValueFormat } from '../../../core/utils';

import { Grid, Typography, Box } from '@mui/material';
import { IItem } from '../../../core/Interface/dashboard.interface';
import * as React from 'react';
import { HEADER_GRADIENT } from '../../../theme/appColors';

interface HeroBannerProps {
  isLoading: boolean;
  topItems: IItem[];
}

const HeroBanner = ({ isLoading, topItems }: HeroBannerProps) => (
  <Box
    sx={{
      mb: 2,
      px: { xs: 2, md: 3 },
      py: { xs: 1.5, md: 2 },
      borderRadius: 2,
      color: '#fff',
      background: HEADER_GRADIENT,
      // boxShadow: '0 28px 60px rgba(15, 29, 77, 0.24)',
      position: 'relative',
      overflow: 'hidden',
    }}
  >
    <Box
      sx={{
        position: 'absolute',
        inset: 'auto -60px -120px auto',
        width: 240,
        height: 240,
        borderRadius: '50%',
        background: 'rgba(255,255,255,0.08)',
        pointerEvents: 'none',
      }}
    />
    <Box
      sx={{
        position: 'absolute',
        inset: '-120px auto auto 55%',
        width: 280,
        height: 280,
        borderRadius: '50%',
        background: 'rgba(255,255,255,0.06)',
        pointerEvents: 'none',
      }}
    />

    <Grid
      alignItems="center"
      container
      spacing={{ xs: 1.5, md: 3 }}
      sx={{ position: 'relative' }}
    >
      <Grid
        item
        xs={12}
        md={7}
        lg={7}
      >
        <Typography
          sx={{
            fontSize: { xs: '1rem', md: '1.35rem' },
            fontWeight: 700,
            lineHeight: 1.15,
            letterSpacing: '-0.02em',
            maxWidth: 620,
            color: '#dedede',
            textShadow: '0 2px 12px rgba(10, 15, 42, 0.28)',
          }}
        >
          Sales Performance at a Glance
        </Typography>
        <Typography
          sx={{
            display: { xs: 'none', sm: 'block' },
            mt: 0.75,
            maxWidth: 620,
            color: 'rgba(255,255,255,0.82)',
            fontSize: { xs: '0.82rem', md: '0.88rem' },
            lineHeight: 1.55,
          }}
        >
          {/* eslint-disable-next-line max-len */}
          Track today's revenue, customer activity, and product trends in real time — with
          weekly charts and category insights to guide smarter decisions.
        </Typography>
      </Grid>

      <Grid
        item
        xs={12}
        md={5}
        lg={5}
      >
        <Grid
          container
          spacing={1.5}
        >
          {isLoading
            ? [0, 1, 2, 3].map((i) => (
                <Grid
                  item
                  key={i}
                  xs={6}
                >
                  <Box
                    sx={{
                      p: { xs: 1.25, sm: 2 },
                      borderRadius: '20px',
                      border: '1px solid rgba(255,255,255,0.12)',
                      backgroundColor: 'rgba(255,255,255,0.1)',
                      height: { xs: 60, sm: 76 },
                    }}
                  />
                </Grid>
              ))
            : topItems.slice(0, 4).map((tile) => (
                <Grid
                  item
                  key={tile.key}
                  xs={6}
                >
                  <Box
                    sx={{
                      p: { xs: 1.25, sm: 2 },
                      borderRadius: 2,
                      border: '1px solid rgba(255,255,255,0.12)',
                      backgroundColor: 'rgba(255,255,255,0.1)',
                      backdropFilter: 'blur(12px)',
                    }}
                  >
                    <Typography
                      sx={{
                        fontSize: { xs: '0.65rem', sm: '0.72rem' },
                        textTransform: 'uppercase',
                        letterSpacing: { xs: '0.06em', sm: '0.12em' },
                        wordBreak: 'break-word',
                        color: 'rgba(255,255,255,0.68)',
                        mb: 0.75,
                        fontWeight:600
                      }}
                    >
                      {tile.key}
                    </Typography>
                    <Typography
                      sx={{
                        fontSize: { xs: '0.92rem', sm: '1rem' },
                        fontWeight: 700,
                        lineHeight: 1.2,
                        wordBreak: 'break-word',
                      }}
                    >
                      {getMetricValueFormat(tile.key, tile.value)}
                    </Typography>
                  </Box>
                </Grid>
              ))}
        </Grid>
      </Grid>
    </Grid>
  </Box>
);

export default HeroBanner;
