import React from 'react';
import { appColors } from '../../../theme/appColors';
import HighchartsReact from 'highcharts-react-official';
import Highcharts from 'highcharts';
import { useIsSmallScreen } from '../../../core/utils';

interface IPieChart {
  chartDescription: string;
  data: (string | number)[][];
}

const PieChart = (props: IPieChart) => {
  const { chartDescription, data } = props;
  const isSmall = useIsSmallScreen();

  return (
    <HighchartsReact
      containerProps={{ style: { width: '100%' } }}
      highcharts={Highcharts}
      options={{
        chart: {
          type: 'pie',
          backgroundColor: 'transparent',
          reflow: true,
          height: isSmall ? 320 : 400,
          options3d: { enabled: true, alpha: 45 },
        },
        legend: {
          enabled: isSmall,
          itemStyle: { color: appColors.reflexBlue[80], fontWeight: '600' },
        },
        title: { text: '' },
        subtitle: { text: '' },
        tooltip: {
          pointFormat: `<span style="color: ${appColors.carmineRed[60]}">{series.name} <b>{point.percentage:.1f}%</b></span>`,
          backgroundColor: appColors.persianBlue[20],
        },
        plotOptions: {
          pie: {
            allowPointSelect: true,
            cursor: 'pointer',
            innerSize: isSmall ? 80 : 100,
            depth: 35,
            showInLegend: isSmall,
            dataLabels: {
              enabled: !isSmall,
              format: `<b style="color: ${appColors.reflexBlue[80]}">{point.name}</b>`,
            },
          },
        },
        credits: { enabled: false },
        accessibility: { enabled: false },
        series: [{ name: chartDescription, data }],
      }}
    />
  );
};

export default React.memo(PieChart);
